"""The recommendations service the shop depends on, with a fault-injection switch for chaos experiments."""
import asyncio
import random

from fastapi import FastAPI, HTTPException

app = FastAPI()
fault = {"latency_ms": 0, "error_rate": 0.0}
rng = random.Random(42)


@app.get("/health")
async def health():
    return {"status": "ok"}


@app.get("/recommendations/{user_id}")
async def recommendations(user_id: int):
    if fault["latency_ms"]:
        await asyncio.sleep(fault["latency_ms"] / 1000)
    if rng.random() < fault["error_rate"]:
        raise HTTPException(status_code=503, detail="injected failure")
    return {"user_id": user_id, "items": [101, 205, 309]}


@app.post("/chaos")
async def set_fault(latency_ms: int = 0, error_rate: float = 0.0):
    """Inject latency and errors; POST /chaos with no parameters removes the fault."""
    fault.update(latency_ms=latency_ms, error_rate=error_rate)
    return fault
